# ---------------------------------------------------------
# PDFプレビュー & 印刷機能
# ---------------------------------------------------------
def render_pdf_preview_and_print(pdf_bytes: bytes):
    base64_pdf = base64.b64encode(pdf_bytes).decode("utf-8")

    print_html = f"""
    <!DOCTYPE html>
    <html>
    <head>
        <meta charset="utf-8">
        <style>
            .print-btn {{
                background-color: #2563eb;
                color: white;
                border: none;
                padding: 12px 24px;
                font-size: 16px;
                font-weight: bold;
                border-radius: 8px;
                cursor: pointer;
                box-shadow: 0 4px 6px rgba(0,0,0,0.1);
                width: 100%;
                text-align: center;
                font-family: sans-serif;
            }}
            .print-btn:hover {{
                background-color: #1d4ed8;
            }}
        </style>
    </head>
    <body>
        <button class="print-btn" onclick="openPrintWindow()">このまま印刷する</button>
        <script>
            function openPrintWindow() {{
                const pdfData = "{base64_pdf}";
                const byteCharacters = atob(pdfData);
                const byteNumbers = new Array(byteCharacters.length);
                for (let i = 0; i < byteCharacters.length; i++) {{
                    byteNumbers[i] = byteCharacters.charCodeAt(i);
                }}
                const byteArray = new Uint8Array(byteNumbers);
                const blob = new Blob([byteArray], {{type: 'application/pdf'}});
                const blobUrl = URL.createObjectURL(blob);
                const printWindow = window.open(blobUrl, '_blank');
                if (printWindow) {{
                    printWindow.onload = function() {{
                        printWindow.print();
                    }};
                }}
            }}
        </script>
    </body>
    </html>
    """

    st.markdown("### プレビュー & 印刷")
    components.html(print_html, height=65)
    st.markdown("---")

    try:
        doc = fitz.open(stream=pdf_bytes, filetype="pdf")
        for page_num in range(len(doc)):
            page = doc.load_page(page_num)
            pix = page.get_pixmap(dpi=150)
            img = Image.open(io.BytesIO(pix.tobytes("png")))

            st.image(
                img,
                caption=f"第 {page_num + 1} / {len(doc)} ページ",
                width=500,
            )
            if page_num < len(doc) - 1:
                st.markdown("---")
    except Exception as e:
        st.error(f"プレビューの生成に失敗しました: {e}")


# ---------------------------------------------------------
# LaTeXコンパイル関数
# ---------------------------------------------------------
def compile_latex_to_pdf(latex_code: str) -> bytes:
    with tempfile.TemporaryDirectory() as tmpdir:
        tex_path = os.path.join(tmpdir, "output.tex")
        with open(tex_path, "w", encoding="utf-8") as f:
            f.write(latex_code)

        try:
            subprocess.run(
                ["lualatex", "-interaction=nonstopmode", "output.tex"],
                cwd=tmpdir,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                check=True,
            )
            pdf_path = os.path.join(tmpdir, "output.pdf")
            if os.path.exists(pdf_path):
                with open(pdf_path, "rb") as f:
                    return f.read()
        except subprocess.CalledProcessError as e:
            st.error("LaTeXのコンパイルエラーが発生しました。")
            log_path = os.path.join(tmpdir, "output.log")
            if os.path.exists(log_path):
                with open(log_path, "r", encoding="utf-8", errors="ignore") as log_f:
                    st.text_area("コンパイルログ", log_f.read(), height=200)
            raise e

    return b""


# ---------------------------------------------------------
# 単元選択・出題数設定・PDFプレビュー
# ---------------------------------------------------------
def collect_units(data, path=()):
    """問題データをたどり、問題リストを持つ最小単位を集める。"""
    units = []
    if isinstance(data, list):
        if data:
            units.append((path, data))
    elif isinstance(data, dict):
        for name, value in data.items():
            units.extend(collect_units(value, path + (name,)))
    return units


def clean_unit_title(name):
    """表示名から「第1章」「第1節」などの番号部分を取り除く。"""
    import re
    name = re.sub(r"^第[0-9０-９一二三四五六七八九十百]+章\s*", "", name)
    name = re.sub(r"^第[0-9０-９一二三四五六七八九十百]+節\s*", "", name)
    return name


def render_unit_checkboxes(all_units):
    """最小単元を、列幅が崩れない編集可能な表として表示する。"""
    import pandas as pd

    rows = []
    previous_path = []
    for unit_path, questions in all_units:
        cleaned = [clean_unit_title(part) for part in unit_path]
        levels = (cleaned + [""] * 5)[:5]
        shown = levels.copy()
        # 親単元は同じまとまりの先頭行だけに表示する。
        for i in range(min(4, len(cleaned), len(previous_path))):
            if cleaned[i] == previous_path[i] and all(
                cleaned[j] == previous_path[j] for j in range(i)
            ):
                shown[i] = ""
            else:
                break

        # 最小単元がある行では、一つ手前の階層名を取り除き、
        # 最小単元名をその空欄へ左詰めする。右端が空欄の行は変更しない。
        if shown[4]:
            shown[3] = shown[4]
            shown[4] = ""

        checkbox_key = "unit_" + "__".join(unit_path)
        rows.append({
            "階層1": shown[0],
            "階層2": shown[1],
            "階層3": shown[2],
            "階層4": shown[3],
            "問題数": f"全{len(questions)}問",
            "選択": bool(st.session_state.get(checkbox_key, False)),
            "_path": unit_path,
        })
        previous_path = cleaned

    # 空欄になっていた「最小単元」列は削除し、単元名は階層4列に左詰めして表示する。
    columns = ["階層1", "階層2", "階層3", "階層4", "問題数", "選択"]
    df = pd.DataFrame([{key: row[key] for key in columns} for row in rows])
    # データエディタの列見出し（薄いグレーの行）を隠し、
    # 全行が画面内に収まる高さにする。表の外側ではなくページ上に直接表示する。
    st.markdown(
        """
        <style>
        [data-testid="stDataEditor"] [role="columnheader"] {
            display: none !important;
        }
        [data-testid="stDataEditor"] [role="row"] {
            min-height: 34px !important;
        }
        </style>
        """,
        unsafe_allow_html=True,
    )
    edited = st.data_editor(
        df,
        key="unit_selection_editor",
        hide_index=True,
        num_rows="fixed",
        use_container_width=True,
        height=max(80, len(df) * 34 + 8),
        row_height=34,
        disabled=columns[:-1],
        column_config={
            "階層1": st.column_config.TextColumn("", width="small"),
            "階層2": st.column_config.TextColumn("", width="small"),
            "階層3": st.column_config.TextColumn("", width="small"),
            "階層4": st.column_config.TextColumn("", width="large"),
            "問題数": st.column_config.TextColumn("", width="small"),
            "選択": st.column_config.CheckboxColumn("", width="small"),
        },
    )
    for i, row in enumerate(rows):
        checkbox_key = "unit_" + "__".join(row["_path"])
        st.session_state[checkbox_key] = bool(edited.iloc[i]["選択"])

def get_selected_units(all_units):
    """選択画面のチェック状態から、選択済み小単元を取得する。"""
    selected = {}
    for path, questions in all_units:
        checkbox_key = "unit_" + "__".join(path)
        if st.session_state.get(checkbox_key, False):
            selected[" > ".join(path)] = questions
    return selected


