if "selection_step" not in st.session_state:
    st.session_state["selection_step"] = "units"

if st.session_state["selection_step"] == "units":
    st.subheader("① 出題する単元を選択")
    # 列見出しは省略し、単元一覧だけをコンパクトに表示する。
    render_unit_checkboxes(all_units)

    st.markdown("---")
    if st.button("選択した単元を決定", type="primary"):
        selected = get_selected_units(all_units)
        if not selected:
            st.warning("少なくとも1つの小単元を選択してください。")
        else:
            st.session_state["selected_units"] = selected
            st.session_state["selection_step"] = "counts"
            st.session_state.pop("pdf_data", None)
            st.rerun()

else:
    st.subheader("② 単元ごとの問題数を設定")
    st.write("選択した小単元だけを表示しています。各単元から出題する問題数を決めてください。")

    selected_units_config = {}
    for unit_label, questions in st.session_state.get("selected_units", {}).items():
        max_q = len(questions)
        with st.container(border=True):
            label_col, count_col, suffix_col = st.columns(
                [8, 2, 1], vertical_alignment="center"
            )
            display_unit_label = " > ".join(clean_unit_title(part) for part in unit_label.split(" > "))
            label_col.markdown(f"**{display_unit_label}**（全 {max_q} 問）")
            num_q = count_col.number_input(
                "出題数",
                min_value=1,
                max_value=max_q,
                value=1,
                step=1,
                key="count_" + unit_label,
                label_visibility="collapsed",
            )
            suffix_col.markdown("問")
        selected_units_config[unit_label] = (questions, int(num_q))

    st.markdown("---")
    back_col, preview_col = st.columns([1, 2])
    with back_col:
        if st.button("単元選択に戻る"):
            st.session_state["selection_step"] = "units"
            st.session_state.pop("pdf_data", None)
            st.rerun()

    with preview_col:
        preview_clicked = st.button("プレビューを表示", type="primary")

    if preview_clicked:
        # 修正点: \package -> \usepackage
        latex_source = f"""
        \\documentclass[11pt,a4paper]{{ltjsarticle}}
        \\usepackage{{amsmath,amssymb,amsthm}}
        \\everymath{{\\displaystyle}}
        \\begin{{document}}
        \\begin{{center}}
            {{\\Large \\textbf{{数学のガチャ}}}}
        \\end{{center}}
        \\vspace{{1em}}
        \\noindent \\textbf{{氏名: \\underline{{\\hspace{{5cm}}}}}}
        \\vspace{{1.5em}}
        \\hrule
        \\vspace{{1em}}
        """

        units_list = list(selected_units_config.items())
        random.shuffle(units_list)

        global_q_index = 1
        for cat_name, (q_list, count) in units_list:
            selected_questions = random.sample(q_list, count)
            for q_text in selected_questions:
                latex_source += f"""
                \\begin{{samepage}}
                \\noindent \\textbf{{({global_q_index})}} {q_text}
                \\vspace{{1.5em}}
                \\end{{samepage}}
                """
                global_q_index += 1

        latex_source += """
        \\end{document}
        """

        with st.spinner("PDFをコンパイル中..."):
            try:
                pdf_data = compile_latex_to_pdf(latex_source)
                st.session_state["pdf_data"] = pdf_data
                st.success("プレビューの生成が完了しました！")
            except Exception:
                st.error("PDFの生成に失敗しました。")

    # 生成されたPDFがある場合の表示
    if "pdf_data" in st.session_state:
        st.markdown("---")
        render_pdf_preview_and_print(st.session_state["pdf_data"])

        st.download_button(
            label="生成されたPDFをダウンロード",
            data=st.session_state["pdf_data"],
            file_name="math_ガチャ.pdf",
            mime="application/pdf",
        )
